static void draw_sprite(uint16_t* pause_frame, int dst_pitch, int screen_width, int screen_height,
    const uint16_t* sprite, int width, int height, int x, int y) {
    if (x >= screen_width || y >= screen_height || x + width <= 0 || y + height <= 0)
        return;

    int start_y = (y < 0) ? -y : 0;
    int end_y = (y + height > screen_height) ? screen_height - y : height;
    int start_x = (x < 0) ? -x : 0;
    int end_x = (x + width > screen_width) ? screen_width - x : width;

    for (int sy = start_y; sy < end_y; sy++) {
        uint16_t* dest_line = &pause_frame[(y + sy) * dst_pitch + x + start_x];
        const uint16_t* src_line = &sprite[sy * width + start_x];

        for (int sx = start_x; sx < end_x; sx++)
            if (src_line[sx - start_x] != 0xffff) // white = transparent color
                dest_line[sx - start_x] = src_line[sx - start_x];
    }
}

static void draw_overlay_progress_bar(uint16_t* pause_frame, 
                            int dst_pitch, int screen_width, int screen_height) {
    int enemy_x;
    int enemy_y;

    if (rg_main.glitch_count > 2) {
        // PIXEL_ART_ENEMY
        enemy_x = 10;
        enemy_y = screen_height - ENEMY_HEIGHT - 20;
        draw_sprite(pause_frame, dst_pitch, screen_width, screen_height,
            pixel_art_enemy,
            ENEMY_WIDTH, ENEMY_HEIGHT,
            enemy_x, enemy_y);
    }
    else {
        // PIXEL_ART_ENEMY_DOWN
        enemy_x = 10;
        enemy_y = screen_height - ENEMY_DOWN_HEIGHT - 24;
        draw_sprite(pause_frame, dst_pitch, screen_width, screen_height,
            pixel_art_enemy_down,
            ENEMY_DOWN_WIDTH, ENEMY_DOWN_HEIGHT,
            enemy_x, enemy_y);
    }

    // PIXEL_ART_HERO
    int hero_x = screen_width - HERO_WIDTH - 10;
    int hero_y = screen_height - HERO_HEIGHT - 20;
    draw_sprite(pause_frame, dst_pitch, screen_width, screen_height,
        pixel_art_hero, 
        HERO_WIDTH, HERO_HEIGHT,
        hero_x, hero_y);

    // PIXEL_ART_DOT
    int progress = rg_total_glitch_count - rg_main.glitch_count;
    if (progress > 0 && rg_main.glitch_count > 2) {
        int dot_start_x = hero_x - DOT_WIDTH;
        int dot_end_x = enemy_x + ENEMY_WIDTH - 10;
        int dot_x = dot_start_x - (progress * (dot_start_x - dot_end_x)) / rg_total_glitch_count;
        int dot_y = hero_y + 16;

        draw_sprite(pause_frame, dst_pitch, screen_width, screen_height,
            pixel_art_dot, DOT_WIDTH, DOT_HEIGHT, dot_x, dot_y);
    }
}

